/**
 * Create or replay an immutable artifact replication plan
 *
 * Newly accepted plans persist both the immutable source coordinate and
 * digest; neither field may be present without the other. A request-time
 * quarantine denial returns 403 without creating a plan. If the final
 * worker check instead observes quarantine, it parks the existing plan
 * without publishing target metadata. After release, replaying the exact
 * request with the same Idempotency-Key requeues and returns that plan; it
 * does not create a second plan. A PyPI source version whose file membership
 * changes after enqueue is likewise parked with
 * `replication_snapshot_changed`; exact replay atomically refreshes that
 * plan's checkpoints before requeueing the same plan ID.
 *
 */
export const createRepositoryReplication = <ThrowOnError extends boolean = false>(options: Options<CreateRepositoryReplicationData, ThrowOnError>): RequestResult<CreateRepositoryReplicationResponses, CreateRepositoryReplicationErrors, ThrowOnError> => (options.client ?? client).post<CreateRepositoryReplicationResponses, CreateRepositoryReplicationErrors, ThrowOnError>({
    security: [{
            key: 'bearerAuth',
            scheme: 'bearer',
            type: 'http'
        }],
    url: '/repositories/{repositoryId}/replications',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Cancel a pending or failed replication plan
 *
 * Stops a pending or failed replication plan from being claimed again. A
 * running plan cannot be cancelled because the worker owns it mid-flight;
 * such a request fails with 409. Completed and already-cancelled plans are
 * also not cancellable. The plan record is retained for audit.
 *
 */
export const deleteRepositoryReplication = <ThrowOnError extends boolean = false>(options: Options<DeleteRepositoryReplicationData, ThrowOnError>): RequestResult<DeleteRepositoryReplicationResponses, DeleteRepositoryReplicationErrors, ThrowOnError> => (options.client ?? client).delete<DeleteRepositoryReplicationResponses, DeleteRepositoryReplicationErrors, ThrowOnError>({
    security: [{
            key: 'bearerAuth',
            scheme: 'bearer',
            type: 'http'
        }],
    url: '/repositories/{repositoryId}/replications/{replicationPlanId}',
    ...options
});

